type A2UIElement = string; // ID of the referenced component
type Action = string; // An inline Event(...) call or catalog function call expression, e.g. "{Event('click', {arg: $/path})}" or "{openUrl(url: '...')}"
type FunctionCall = string; // A catalog function call expression, e.g. "{formatString('Title: ${/path}')}" or "{regex(pattern: '^[A-Z]')}" 

// Tag: <ui-audio-player>
interface AudioPlayer {
  id?: string;
  // The URL of the audio to be played.
  url: string | DataBinding;
  // A description of the audio, such as a title or summary.
  description?: string | DataBinding;
  // The relative weight of this component within a Row or Column. This is similar to the CSS 'flex-grow' property. Note: this may ONLY be set when the component is a direct descendant of a Row or Column.
  weight?: number;
}

// Tag: <ui-button>
interface Button {
