  allowedTools?: string[];
  // List of local function names the app is allowed to call.
  allowedFunctions?: string[];
  // The A2UI data model path or value bound to this component for reactive state synchronization.
  data?: any;
}

// Tag: <ui-pong-layout>
interface PongLayout {
  id?: string;
